<template><NuxtLayout><h1>Patch Panel & Cable Mapping</h1><p class="muted">Connect switch ports to patch panels and other network equipment. Each port can have only one direct cable connection.</p><div class="panel"><h2>New cable connection</h2><div class="fields"><label>From device<select v-model="deviceA"><option value="">Choose device</option><option v-for="d in devices.filter(x=>x.port_count)" :key="d.id" :value="String(d.id)">{{d.name}}</option></select></label><label>From port<select v-model="portA"><option value="">Choose port</option><option v-for="p in ports.filter(x=>String(x.device_id)===deviceA)" :key="p.id" :value="String(p.id)">Port {{p.port_number}}</option></select></label><label>To device<select v-model="deviceB"><option value="">Choose device</option><option v-for="d in devices.filter(x=>x.port_count)" :key="d.id" :value="String(d.id)">{{d.name}}</option></select></label><label>To port<select v-model="portB"><option value="">Choose port</option><option v-for="p in ports.filter(x=>String(x.device_id)===deviceB)" :key="p.id" :value="String(p.id)">Port {{p.port_number}}</option></select></label><label>Cable label<input v-model="label" placeholder="CAB-001"></label><label>Cable type<select v-model="cableType"><option>Cat5e</option><option>Cat6</option><option>Cat6A</option><option>Fibre SM</option><option>Fibre MM</option><option>DAC</option><option>Other</option></select></label></div><p v-if="error" class="error">{{error}}</p><button :disabled="!editable||!portA||!portB" @click="connect">Save connection</button></div><section class="panel"><h2>Connection map</h2><div class="table-wrap"><table><thead><tr><th>Source</th><th></th><th>Destination</th><th>Label</th><th>Type</th><th></th></tr></thead><tbody><tr v-for="c in connections" :key="c.id"><td><strong>{{c.a_device}}</strong> · Port {{c.a_number}}</td><td>⟷</td><td><strong>{{c.b_device}}</strong> · Port {{c.b_number}}</td><td>{{c.cable_label||'—'}}</td><td>{{c.cable_type}}</td><td><button :disabled="!editable" @click="remove(c.id)">Disconnect</button></td></tr></tbody></table></div><p v-if="!connections.length" class="muted">No connections recorded yet.</p></section></NuxtLayout></template><script setup lang="ts">const auth=useAuth(),editable=computed(()=>['admin','editor'].includes(auth.value?.role));const {data:devices}=await useFetch<any[]>('/api/devices',{default:()=>[]});const {data:ports}=await useFetch<any[]>('/api/ports',{default:()=>[]});const {data:connections,refresh}=await useFetch<any[]>('/api/connections',{default:()=>[]});const deviceA=ref(''),deviceB=ref(''),portA=ref(''),portB=ref(''),label=ref(''),cableType=ref('Cat6'),error=ref('');watch(deviceA,()=>portA.value='');watch(deviceB,()=>portB.value='');async function connect(){error.value='';try{await $fetch('/api/connections',{method:'POST',body:{port_a_id:Number(portA.value),port_b_id:Number(portB.value),cable_label:label.value,cable_type:cableType.value}});portA.value='';portB.value='';label.value='';await refresh()}catch(e:any){error.value=e?.data?.statusMessage||'Could not connect ports'}}async function remove(id:number){if(!confirm('Remove this connection?'))return;error.value='';try{await $fetch(`/api/connections/${id}`,{method:'DELETE'});await refresh()}catch(e:any){error.value=e?.data?.statusMessage||'Could not disconnect'}} </script>
